<template><view class="page"><view class="nav"><text @tap="uni.navigateBack()">‹</text><strong>确认行程费用</strong></view><view class="card"><view class="row"><text>停车费</text><input v-model.number="parking" type="digit" placeholder="0.00"/></view><view class="row"><text>其他费用</text><input v-model.number="other" type="digit" placeholder="0.00"/></view><view class="row"><text>费用备注</text><input v-model="remark" placeholder="选填"/></view><view class="hint">最终距离和时间由服务器根据行程定位记录重新计算，页面输入不能修改总价。</view><button class="primary" :loading="loading" @tap="submit">提交最终费用</button></view></view></template>
<script setup lang="ts">import{ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import{rideApi}from'../../../services/ride';let id=0;const parking=ref(0),other=ref(0),remark=ref(''),loading=ref(false);async function submit(){loading.value=true;try{const extraFees:any[]=[];if(parking.value>0)extraFees.push({type:'PARKING',amount:Number(parking.value),remark:remark.value});if(other.value>0)extraFees.push({type:'OTHER',amount:Number(other.value),remark:remark.value});await rideApi.finalize(id,{finalDistanceMeters:0,finalDurationSeconds:0,extraFees});uni.redirectTo({url:`/pages/ride/detail/index?id=${id}&driver=1`})}catch(e:any){uni.showToast({title:e?.message||'费用确认失败',icon:'none'})}finally{loading.value=false}}onLoad((q:any)=>id=Number(q?.id||0))</script>
<style scoped>.page{min-height:100vh;background:#f1f5f9;padding:24rpx;box-sizing:border-box}.nav{display:flex;align-items:center;gap:18rpx;padding:20rpx 0}.nav text{font-size:50rpx}.card{background:#fff;border-radius:28rpx;padding:24rpx}.row{display:flex;align-items:center;justify-content:space-between;padding:22rpx 0;border-bottom:1px solid #e2e8f0}.row input{text-align:right}.hint{padding:22rpx 0;color:#64748b;font-size:23rpx}.primary{background:#0f172a;color:#fff}</style>
